import React, { useState } from 'react';
import './Portfolio.css';

const Portfolio = () => {
    const [filter, setFilter] = useState('*');

    const projects = [
        {
            id: 1,
            title: 'INTERFACE MOBILE',
            category: 'filter-app',
            image: '/assets/img/portfolio/thumbnail/INTERFACE-MOBILE.png',
            details: 'portfolio-detailsInterfaceMobile.html'
        },
        {
            id: 2,
            title: 'SISTEMA WEB PARA A GESTÃO DE FARMACIA',
            category: 'filter-web',
            image: '/assets/img/portfolio/thumbnail/SISTEMA-WEB-PARA-A-GESTÃO-DE-FARMACIA.png',
            details: 'portfolio-detailsSiscure.html'
        },
        {
            id: 3,
            title: 'PROJETO EM REACT NATIVE',
            category: 'filter-app',
            image: '/assets/img/portfolio/thumbnail/PROJETO-EM-REACT-NATIVE.png',
            details: 'portfolio-detailsProjetoEmReactNative.html'
        },
        {
            id: 4,
            title: 'BEEP SAÚDE FRONT END',
            category: 'filter-web',
            image: '/assets/img/portfolio/thumbnail/BEEP-SAUDE-FRONT-END.png',
            details: 'portfolio-detailsBeep.html'
        },
        {
            id: 5,
            title: 'PROJETO CRUD',
            category: 'filter-web',
            image: '/assets/img/portfolio/thumbnail/PROJETO-CRUD.png',
            details: 'portfolio-detailsProjetoCrud.html'
        },
        {
            id: 6,
            title: 'WEB SCRAPING',
            category: 'filter-card',
            image: '/assets/img/portfolio/thumbnail/WEB-SCRAPING.png',
            details: 'portfolio-detailsWebScraping.html'
        },
        {
            id: 7,
            title: 'EXTRATOR DE TEXTO DE PDF',
            category: 'filter-card',
            image: '/assets/img/portfolio/thumbnail/Extrator-de-Texto-de-PDF.png',
            details: 'portfolio-detailsExtrator.html'
        },
        {
            id: 8,
            title: 'WEB TEST AUTOMATION',
            category: 'filter-card',
            image: '/assets/img/portfolio/thumbnail/WEB-TEST-AUTOMATION.png',
            details: 'portfolio-detailsweb-test-automation.html'
        },
        {
            id: 9,
            title: 'GUIA DE PAGAMENTO',
            category: 'filter-web',
            image: '/assets/img/portfolio/thumbnail/Guia-de-pagamento.png',
            details: 'portfolio-detailsGuiaDePagamento.html'
        },
        {
            id: 10,
            title: 'LOCALHOST',
            category: 'filter-web',
            image: '/assets/img/portfolio/thumbnail/Localhost.png',
            details: 'portfolio-detailsLocalhost.html'
        },
        {
            id: 11,
            title: 'ROCKET CHAT',
            category: 'filter-web',
            image: '/assets/img/portfolio/thumbnail/Rocket-chat.png',
            details: 'portfolio-detailsRocket.html'
        }
    ];

    const filteredProjects = filter === '*'
        ? projects
        : projects.filter(project => project.category === filter);

    return (
        <section id="portfolio" className="portfolio section-bg bg-dark text-white">
            <div className="container">
                <div className="section-title">
                    <h2 className="text-white">Projetos</h2>
                </div>

                <div className="row" data-aos="fade-up">
                    <div className="col-lg-12 d-flex justify-content-center">
                        <ul id="portfolio-flters">
                            <li
                                className={filter === '*' ? 'filter-active' : ''}
                                onClick={() => setFilter('*')}
                            >
                                Todos
                            </li>
                            <li
                                className={filter === 'filter-app' ? 'filter-active' : ''}
                                onClick={() => setFilter('filter-app')}
                            >
                                React Native
                            </li>
                            <li
                                className={filter === 'filter-card' ? 'filter-active' : ''}
                                onClick={() => setFilter('filter-card')}
                            >
                                Node.js
                            </li>
                            <li
                                className={filter === 'filter-web' ? 'filter-active' : ''}
                                onClick={() => setFilter('filter-web')}
                            >
                                Web
                            </li>
                        </ul>
                    </div>
                </div>

                <div className="row portfolio-container" data-aos="fade-up" data-aos-delay="100">
                    {filteredProjects.map(project => (
                        <div key={project.id} className={`col-lg-4 col-md-6 portfolio-item ${project.category}`}>
                            <div className="portfolio-wrap">
                                <img src={project.image} className="img-fluid" alt={project.title} />
                                <div className="portfolio-links">
                                    <a href={project.image} data-gallery="portfolioGallery" className="portfolio-lightbox">
                                        <i className="fa fa-eye"></i>
                                    </a>
                                    <a href={project.details} title="Mais Detalhes">
                                        <i className="fa fa-link"></i>
                                    </a>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </section>
    );
};

export default Portfolio;
